#!/usr/bin/env node
/**
 * v2.2.0 keyword migration: `valuetype is` → `value type is`.
 *
 * Touches every place the literal `valuetype is` appears as the CRL
 * keyword — .crl files, embedded CRL test fixtures inside .ts/.mjs,
 * the TextMate injection grammar, the extension's hover/completion
 * regexes, and docs. Regression snapshots (.tokens / .parse) are
 * regenerated by the test suite — this script does NOT touch them.
 *
 * Run: node scripts/migrate-valuetype-is.js
 */
const fs = require("fs");
const path = require("path");
const { execSync } = require("child_process");

const ROOT = path.resolve(__dirname, "..");

const tracked = execSync("git ls-files", { cwd: ROOT, encoding: "utf8" })
  .trim()
  .split("\n");

// Files to skip wholesale — historical release notes, .cql files (their
// `valuetype` semantics belong to CQL, not CRL), and the regression
// snapshots which get regenerated from the migrated corpus.
const SKIP_FILES = new Set([
  "RELEASE_NOTES_v2.1.0.md",
  "RELEASE_NOTES_v2.0.0.md",
  "src/tests/regression/testdata/regression-lexer-expected.tokens",
  "src/tests/regression/testdata/regression-parser-expected.parse",
  "src/tests/regression/testdata/regression-ast-expected.json",
]);
const SKIP_DIR_PREFIXES = [
  "cql/",                  // CQL source — different semantic
  "node_modules/",
  "dist/",
];
const SKIP_EXTS = new Set([
  ".tgz",
  ".vsix",
  ".png",
  ".pdf",
]);

function shouldSkip(rel) {
  if (SKIP_FILES.has(rel)) return true;
  for (const pfx of SKIP_DIR_PREFIXES) {
    if (rel.startsWith(pfx)) return true;
  }
  const ext = path.extname(rel);
  if (SKIP_EXTS.has(ext)) return true;
  return false;
}

// Pattern matrix — each is applied to every (non-skipped) tracked file.
// Order matters: more-specific patterns first.
const SUBSTITUTIONS = [
  // CRL body-line keyword: `- valuetype is X.` (with optional indentation
  // and the literal keyword) → `- value type is X.`.
  { pattern: /(^|\n)([ \t]*-\s*)valuetype is /g, replacement: "$1$2value type is " },
  // Inline within strings/comments that quote the keyword as-is.
  // Match the keyword preceded by a non-word char so we don't munge
  // identifiers like `VALUETYPE_IS`.
  { pattern: /([^A-Za-z0-9_-])valuetype is /g, replacement: "$1value type is " },
  // Grammar-token references in tests (TS/MJS): `VALUETYPE_IS` →
  // `VALUE_TYPE_IS`. Word-boundary on both sides.
  { pattern: /\bVALUETYPE_IS\b/g, replacement: "VALUE_TYPE_IS" },
  // Camel-case identifier `valuetype` in extension regexes / catalog
  // labels — only when followed by `\s+is` (the keyword phrase) so we
  // don't touch unrelated `valuetype` words (e.g. in comments about
  // FHIR's value[x] choice element).
  { pattern: /valuetype(\\s\+is|\\s\+is\\s|\s+is\b)/g, replacement: "value type$1" },
];

let totalFiles = 0;
let totalSubs = 0;
const touched = [];

for (const rel of tracked) {
  if (shouldSkip(rel)) continue;
  const abs = path.join(ROOT, rel);
  let text;
  try {
    text = fs.readFileSync(abs, "utf8");
  } catch {
    continue; // binary or unreadable — skip
  }
  if (!text.includes("valuetype")) continue;
  let updated = text;
  let subs = 0;
  for (const { pattern, replacement } of SUBSTITUTIONS) {
    const before = updated;
    updated = updated.replace(pattern, replacement);
    if (updated !== before) {
      subs += (before.match(pattern) || []).length;
    }
  }
  if (updated !== text) {
    fs.writeFileSync(abs, updated, "utf8");
    totalFiles++;
    totalSubs += subs;
    touched.push(`  ${rel}  (${subs} sub${subs === 1 ? "" : "s"})`);
  }
}

console.log(`Migrated valuetype → value type: ${totalFiles} files, ${totalSubs} substitutions`);
if (touched.length > 0) {
  console.log("Touched files:");
  console.log(touched.join("\n"));
}

// Report any remaining `valuetype` occurrences as warnings — they may
// be legitimate (CSS, comments about FHIR datatypes) or escapes the
// migration didn't catch.
const remaining = [];
for (const rel of tracked) {
  if (shouldSkip(rel)) continue;
  const abs = path.join(ROOT, rel);
  let text;
  try {
    text = fs.readFileSync(abs, "utf8");
  } catch {
    continue;
  }
  const hits = (text.match(/valuetype/gi) || []).length;
  if (hits > 0) remaining.push({ rel, hits });
}
if (remaining.length > 0) {
  console.log("\nRemaining `valuetype` occurrences (audit manually if any are the CRL keyword):");
  for (const { rel, hits } of remaining) console.log(`  ${rel}  (${hits})`);
}
